SUPPORTED = ("2025-06-18", "2025-03-26")


def serve(requests, tools):
    responses = []
    initialized = False
    for request in requests:
        has_id = "id" in request
        rid = request.get("id")
        method = request.get("method")
        params = request.get("params") or {}

        if method == "initialize":
            if initialized:
                error = {"code": -32600, "message": "already initialized"}
                if has_id:
                    responses.append({"jsonrpc": "2.0", "id": rid, "error": error})
                continue
            initialized = True
            wanted = params.get("protocolVersion")
            version = wanted if wanted in SUPPORTED else SUPPORTED[0]
            result = {
                "protocolVersion": version,
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "toy-server", "version": "0.1.0"},
            }
        elif not initialized:
            error = {"code": -32600, "message": "server not initialized"}
            if has_id:
                responses.append({"jsonrpc": "2.0", "id": rid, "error": error})
            continue
        elif method == "tools/list":
            result = {"tools": [
                {"name": name,
                 "description": tool["description"],
                 "inputSchema": tool["inputSchema"]}
                for name, tool in tools.items()
            ]}
        elif method == "tools/call":
            name = params.get("name")
            if name not in tools:
                error = {"code": -32602, "message": f"Unknown tool: {name}"}
                if has_id:
                    responses.append({"jsonrpc": "2.0", "id": rid, "error": error})
                continue
            try:
                value = tools[name]["fn"](**(params.get("arguments") or {}))
            except Exception as exc:
                result = {"content": [{"type": "text", "text": str(exc)}],
                          "isError": True}
            else:
                result = {"content": [{"type": "text", "text": str(value)}],
                          "isError": False}
        else:
            error = {"code": -32601, "message": f"Method not found: {method}"}
            if has_id:
                responses.append({"jsonrpc": "2.0", "id": rid, "error": error})
            continue

        if has_id:
            responses.append({"jsonrpc": "2.0", "id": rid, "result": result})
    return responses
